import type { BuildEnvironmentOptions, Plugin } from "vite";
import { isVite6OrLater, isVite8OrLater } from "./utils.js";

/**
 * Hidden source maps for the browser build, for Base44's build environment.
 *
 * `index.ts` adds this plugin only when `BASE44_HIDDEN_SOURCE_MAPS=1`. It sets
 * `build.sourcemap: "hidden"`, so the bundle carries no `sourceMappingURL`
 * comment, and leaves the source text out of the maps. The platform keeps the
 * maps private and uses them to map browser stack traces to the app's files.
 *
 * - Build only (`apply: "build"`): the dev server and `vite preview` never see it.
 * - Browser build only: under Vite's environments (6+) only the client
 *   environment changes, so an SSR or Worker build keeps its own config.
 * - The app's choice wins: a `build.sourcemap` already set, `false` included,
 *   leaves source maps exactly as configured.
 *
 * `sourcemapExcludeSources` covers the bundle's own chunks. Vite bundles web
 * workers separately with only some of those output options, so after bundling
 * any `.map` that still holds source text has it removed: a worker's, or one
 * from any other plugin or future Vite.
 */

type BundlerOutputOptions = Record<string, unknown>;
type BundlerOptions = { output?: BundlerOutputOptions | BundlerOutputOptions[] | undefined } & Record<string, unknown>;
type BuildOptions = BuildEnvironmentOptions & {
  // Vite 8's spelling. Vite 7's types do not know it.
  rolldownOptions?: BundlerOptions;
};

export interface HiddenSourceMapsOptions {
  /** Whether bundler options live under `rolldownOptions`. Defaults to the installed Vite's. */
  rolldown?: boolean;
  /** Whether Vite has environments (`configEnvironment`). Defaults to the installed Vite's. */
  environments?: boolean;
}

const excludeSources = (output: BundlerOutputOptions | undefined): BundlerOutputOptions => ({
  ...output,
  sourcemapExcludeSources: true,
});

/**
 * The build options with hidden, sourceless maps, or `null` when the app chose
 * its own `sourcemap`. Builds new objects all the way down: Vite shares nested
 * build objects between the top-level config and every environment, so editing
 * one in place would leak into the SSR build.
 */
export function withHiddenSourceMaps(
  build: BuildOptions | undefined,
  { rolldown }: { rolldown: boolean }
): BuildOptions | null {
  if (build?.sourcemap !== undefined) return null;

  const key = rolldown ? "rolldownOptions" : "rollupOptions";
  // Vite 8 reads `rolldownOptions`, and aliases `rollupOptions` to it.
  const current = (
    (rolldown ? build?.rolldownOptions ?? build?.rollupOptions : build?.rollupOptions) ?? {}
  ) as BundlerOptions;
  const { output } = current;

  const next = {
    ...build,
    sourcemap: "hidden",
    [key]: {
      ...current,
      // An app may build several outputs; each one leaves its sources out.
      output: Array.isArray(output) ? output.map(excludeSources) : excludeSources(output),
    },
  } as BuildOptions;

  if (rolldown) {
    // Spreading copied the alias as a plain, stale value. Put back the alias
    // Vite 8 itself sets up, so later readers of `rollupOptions` see the same
    // object Vite reads.
    delete next.rollupOptions;
    Object.defineProperty(next, "rollupOptions", {
      get: () => next.rolldownOptions,
      set: (value) => {
        next.rolldownOptions = value;
      },
      configurable: true,
      enumerable: true,
    });
  }
  return next;
}

/** Deletes `sourcesContent` from a map and every section of an indexed map. Whether it found any. */
function deleteSourcesContent(map: unknown): boolean {
  if (!map || typeof map !== "object") return false;
  const record = map as { sourcesContent?: unknown; sections?: unknown };
  let found = false;
  if ("sourcesContent" in record) {
    delete record.sourcesContent;
    found = true;
  }
  // An indexed map holds its maps under `sections[].map`, possibly nested.
  if (Array.isArray(record.sections)) {
    for (const section of record.sections) {
      if (deleteSourcesContent((section as { map?: unknown } | null)?.map)) found = true;
    }
  }
  return found;
}

/**
 * A source map's JSON without its source text, or `null` if it has none.
 * Covers indexed maps, whose sections each carry a map. Throws if `map` is not
 * JSON, so the caller can say a map went out unexamined.
 */
export function withoutSourcesContent(map: string): string | null {
  // Most maps already lack source text; skip parsing what may be megabytes.
  // Source-map generators serialize with JSON.stringify, which never escapes
  // the key.
  if (!map.includes('"sourcesContent"')) return null;
  const parsed = JSON.parse(map);
  return deleteSourcesContent(parsed) ? JSON.stringify(parsed) : null;
}

export function hiddenSourceMapsPlugin({
  rolldown = isVite8OrLater,
  environments = isVite6OrLater,
}: HiddenSourceMapsOptions = {}): Plugin {
  // The builds this plugin gave hidden maps: environment names on Vite 6+, or
  // the one browser build (`true`) on Vite 5. Cleared by `config`, which Vite
  // always runs before `configEnvironment` when it resolves a config.
  const changed = new Set<string | true>();

  return {
    name: "base44-hidden-source-maps",
    apply: "build",
    // Run after other plugins' config hooks, so a source-map choice made by a
    // framework plugin counts as the app's own.
    config: {
      order: "post",
      handler(config, env) {
        changed.clear();
        // Vite 6+ is handled per environment below: the top-level build
        // options feed the SSR environment too.
        if (environments) return;
        // Vite 5 runs an SSR build as its own `vite build --ssr`.
        if (config.build?.ssr || env.isSsrBuild) return;
        const build = withHiddenSourceMaps(config.build, { rolldown });
        if (build) {
          config.build = build;
          changed.add(true);
        }
      },
    },
    configEnvironment: {
      order: "post",
      handler(name, config) {
        if (!environments) return;
        const consumer = config.consumer ?? (name === "client" ? "client" : "server");
        if (consumer !== "client") return;
        const build = withHiddenSourceMaps(config.build, { rolldown });
        // Assigned rather than returned: Vite merges a returned config into the
        // existing one, which would append to an `output` array instead of
        // updating each entry.
        if (build) {
          config.build = build;
          changed.add(name);
        }
      },
    },
    generateBundle: {
      // "post" so Vite's worker plugin has already added each worker's chunk
      // and map to this bundle: it emits them from its own generateBundle.
      order: "post",
      handler(_options, bundle) {
        if (changed.size === 0) return;
        // Only builds this plugin changed. A build whose environment is unknown
        // is stripped rather than skipped: leaving source text in is the
        // failure this step exists to prevent.
        const name = (this as { environment?: { name?: string } }).environment?.name;
        if (environments && name !== undefined && !changed.has(name)) return;
        for (const file of Object.values(bundle)) {
          if (file.type !== "asset" || !file.fileName.endsWith(".map")) continue;
          const text = typeof file.source === "string" ? file.source : new TextDecoder().decode(file.source);
          try {
            const stripped = withoutSourcesContent(text);
            if (stripped !== null) file.source = stripped;
          } catch {
            this.warn(`${file.fileName} is not valid JSON, so its source text could not be removed.`);
          }
        }
      },
    },
  };
}
